import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x, torch::Tensor w);
"""

conv_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled 2D convolution kernel (no padding, stride=1, no bias)
// Loads an input tile (with halo) and the full weight tensor into shared
// memory, then each thread computes one output pixel across all output
// channels.
template <typename T, int TILE>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int Kout, int KH, int KW,
    int Hout, int Wout)
{
    extern __shared__ unsigned char smem_raw[];

    const int SH = TILE + KH - 1;
    const int SW = TILE + KW - 1;

    T* sX_ptr = reinterpret_cast<T*>(smem_raw);
    T* sW_ptr = sX_ptr + (size_t)C * SH * SW;

    // Shared memory tensors
    Tensor sX = make_tensor(make_smem_ptr(sX_ptr),
                             make_shape(C, SH, SW),
                             make_stride(SH * SW, SW, 1));

    Tensor sW = make_tensor(make_smem_ptr(sW_ptr),
                             make_shape(Kout, C, KH, KW),
                             make_stride(C * KH * KW, KH * KW, KW, 1));

    const int n = blockIdx.z;

    const T* Xn = X + (int64_t)n * C * H * Win;
    T* Yn       = Y + (int64_t)n * Kout * Hout * Wout;

    // Global memory tensors
    Tensor mX = make_tensor(make_gmem_ptr(Xn),
                             make_shape(C, H, Win),
                             make_stride((int64_t)H * Win, (int64_t)Win, (int64_t)1));

    Tensor mY = make_tensor(make_gmem_ptr(Yn),
                             make_shape(Kout, Hout, Wout),
                             make_stride((int64_t)Hout * Wout, (int64_t)Wout, (int64_t)1));

    Tensor mW = make_tensor(make_gmem_ptr(W),
                             make_shape(Kout, C, KH, KW),
                             make_stride(C * KH * KW, KH * KW, KW, 1));

    const int ow0 = blockIdx.x * TILE;
    const int oh0 = blockIdx.y * TILE;

    const int tid      = threadIdx.y * TILE + threadIdx.x;
    const int nthreads = TILE * TILE;

    // Cooperative load of the input tile (with halo) into shared memory
    const int total_in = C * SH * SW;
    for (int idx = tid; idx < total_in; idx += nthreads) {
        int c   = idx / (SH * SW);
        int rem = idx % (SH * SW);
        int sh  = rem / SW;
        int sw  = rem % SW;

        int ih = oh0 + sh;
        int iw = ow0 + sw;

        T val = T(0.0f);
        if (ih < H && iw < Win) {
            val = mX(c, ih, iw);
        }
        sX(c, sh, sw) = val;
    }

    // Cooperative load of the weight tensor into shared memory
    const int total_w = Kout * C * KH * KW;
    for (int idx = tid; idx < total_w; idx += nthreads) {
        int oc   = idx / (C * KH * KW);
        int rem  = idx % (C * KH * KW);
        int c    = rem / (KH * KW);
        int rem2 = rem % (KH * KW);
        int kh   = rem2 / KW;
        int kw   = rem2 % KW;

        sW(oc, c, kh, kw) = mW(oc, c, kh, kw);
    }

    __syncthreads();

    const int ow = ow0 + threadIdx.x;
    const int oh = oh0 + threadIdx.y;

    if (oh < Hout && ow < Wout) {
        constexpr int OC_BLOCK = 8;
        for (int oc0 = 0; oc0 < Kout; oc0 += OC_BLOCK) {
            int oc_cnt = Kout - oc0 < OC_BLOCK ? Kout - oc0 : OC_BLOCK;
            float acc[OC_BLOCK];
            #pragma unroll
            for (int t = 0; t < OC_BLOCK; ++t) acc[t] = 0.0f;
            for (int c = 0; c < C; ++c) {
                for (int kh = 0; kh < KH; ++kh) {
                    for (int kw = 0; kw < KW; ++kw) {
                        float xval = float(sX(c, threadIdx.y + kh, threadIdx.x + kw));
                        #pragma unroll
                        for (int t = 0; t < OC_BLOCK; ++t) {
                            if (t < oc_cnt) {
                                float wval = float(sW(oc0 + t, c, kh, kw));
                                acc[t] += xval * wval;
                            }
                        }
                    }
                }
            }
            #pragma unroll
            for (int t = 0; t < OC_BLOCK; ++t) {
                if (t < oc_cnt) {
                    mY(oc0 + t, oh, ow) = T(acc[t]);
                }
            }
        }
    }
}

torch::Tensor conv2d_forward(torch::Tensor x, torch::Tensor w) {
    TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kBFloat16 && w.scalar_type() == at::kBFloat16,
                "expect bfloat16 tensors");
    TORCH_CHECK(x.dim() == 4, "x must be [N,C,H,W]");
    TORCH_CHECK(w.dim() == 4, "w must be [Kout,C,KH,KW]");

    auto x_c = x.contiguous();
    auto w_c = w.contiguous();

    int N   = (int)x_c.size(0);
    int C   = (int)x_c.size(1);
    int H   = (int)x_c.size(2);
    int Win = (int)x_c.size(3);

    int Kout = (int)w_c.size(0);
    TORCH_CHECK((int)w_c.size(1) == C, "input channel mismatch between x and w");
    int KH = (int)w_c.size(2);
    int KW = (int)w_c.size(3);

    int Hout = H - KH + 1;
    int Wout = Win - KW + 1;
    TORCH_CHECK(Hout > 0 && Wout > 0, "invalid computed output size");

    auto y = torch::empty({N, Kout, Hout, Wout}, x_c.options());

    constexpr int TILE = 16;
    dim3 block(TILE, TILE);
    dim3 grid((Wout + TILE - 1) / TILE,
              (Hout + TILE - 1) / TILE,
              N);

    int SH = TILE + KH - 1;
    int SW = TILE + KW - 1;
    size_t smem_size = (size_t)(C * SH * SW + Kout * C * KH * KW) * sizeof(at::BFloat16);

    using T = cute::bfloat16_t;

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv2d_kernel<T, TILE><<<grid, block, smem_size, stream>>>(
        reinterpret_cast<const T*>(x_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<const T*>(w_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<T*>(y.data_ptr<at::BFloat16>()),
        N, C, H, Win, Kout, KH, KW, Hout, Wout
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=conv_cpp_decl,
    cuda_sources=conv_cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # Use a temporary nn.Conv2d only to replicate PyTorch's default weight
        # initialization scheme; its forward() is never called.
        conv = nn.Conv2d(in_channels=3, out_channels=32, kernel_size=3,
                          bias=False, dtype=torch.bfloat16)
        self.weight = nn.Parameter(conv.weight.data.clone())
        self._ext = conv2d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(x.contiguous(), self.weight.contiguous())

